  assert.equal(result, '€1,234.56');
});

test('formatMoney formats USD with dollar sign', () => {
  const result = formatMoney(123456, 'USD');
  assert.equal(result, '$1,234.56');
});

test('formatMoney formats GBP with pound sign', () => {
  const result = formatMoney(123456, 'GBP');
  assert.equal(result, '£1,234.56');
});

test('formatMoney formats negative amounts', () => {
  const eurResult = formatMoney(-123456, 'EUR');
  assert.equal(eurResult, '-€1,234.56');
  const usdResult = formatMoney(-123456, 'USD');
  assert.equal(usdResult, '-$1,234.56');
  const gbpResult = formatMoney(-123456, 'GBP');
  assert.equal(gbpResult, '-£1,234.56');
});

test('formatMoney includes thousands separators', () => {
  const result = formatMoney(1234567, 'USD');
  assert.equal(result, '$12,345.67');
});

test('formatMoney pads decimals to 2 places', () => {
  const result = formatMoney(50, 'USD');
  assert.equal(result, '$0.50');
});

test('formatMoney with zero amount', () => {
  const result = formatMoney(0, 'EUR');
  assert.equal(result, '€0.00');
});

test('formatMoney with unknown currency defaults to EUR', () => {
  const result = formatMoney(123456, 'JPY');
  assert.equal(result, '€1,234.56');
});

test('convert 0 EUR to USD', () => {
  const result = convert(0, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 0);
});

test('convert negative EUR to USD', () => {
  const result = convert(-10000, 'USD');
  assert.equal(result.ok, true);
  assert.ok(result.value < 0);
});

test('convert large amount EUR to USD', () => {
  const result = convert(100000000, 'USD');
  assert.equal(result.ok, true);
  assert.ok(result.value > 100000000);
});

test('convert maintains precision with rounding', () => {
  const result = convert(1, 'USD');
  assert.equal(result.ok, true);
  assert.equal(result.value, 1);
});

test('formatMoney with large amounts', () => {
  const result = formatMoney(99999999, 'USD');
  assert.ok(result.includes('$'));
  assert.ok(result.includes(','));
});

test('convert USD to EUR returns smaller amount', () => {
  const usdResult = convert(100000, 'USD');
  const eurCents = usdResult.value / 1.085;
  assert.ok(eurCents < 100000);
});

